import{_ as e,c as o,o as s,ae as a}from"./chunks/framework.Bi6zybwU.js";const u=JSON.parse('{"title":"WP Posts Table/Custom Post Type Integration","description":"WP Posts Table/Custom Post Type Integration","frontmatter":{"title":"WP Posts Table/Custom Post Type Integration","description":"WP Posts Table/Custom Post Type Integration"},"headers":[],"relativePath":"guide/data-sources/create-wp-posts-table.md","filePath":"guide/data-sources/create-wp-posts-table.md"}'),n={name:"guide/data-sources/create-wp-posts-table.md"};function i(l,t,r,p,h,c){return s(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="wp-posts-table-custom-post-type-integration" tabindex="-1">WP Posts Table/Custom Post Type Integration <a class="header-anchor" href="#wp-posts-table-custom-post-type-integration" aria-label="Permalink to &quot;WP Posts Table/Custom Post Type Integration&quot;">​</a></h1><p>You can create a WP Posts table with Ninja Tables easily. This feature basically shows the WordPress posts on your website in a table format. Bloggers or business owners can use this feature to display the details of their posts/pages in data tables. The table can include a featured image, title, description, link, and even any custom button.</p><h2 id="create-wp-posts-table" tabindex="-1">Create WP Posts Table <a class="header-anchor" href="#create-wp-posts-table" aria-label="Permalink to &quot;Create WP Posts Table&quot;">​</a></h2><p>Let&#39;s dive into this simple guide to demonstrate how to implement this function in detail.</p><ul><li>With the built-in WP Posts feature of Ninja Tables, you can convert your WordPress Pages, Posts/CPT, and WooCommerce items into a table format without installing any additional add-ons like other plugins.</li><li>For instance, there are some pages, blog posts, or customized posts in the WordPress dashboard. Then these items will be displayed in the form of a table. To do this, go to the <strong>Ninja Tables dashboard → Add Table</strong> in the top right corner.</li><li>Then a pop-up box will appear. Click on the <strong>WP Posts</strong> and add a title to your table. <img src="https://ninjatables.com/wp-content/uploads/2022/09/WP-Post-Table-1-scaled.webp" alt=""></li><li>All Post Types, pages, and products will be in the checkbox fields; you can choose as per your requirements.</li><li>A single Post Type is chosen in this example - <img src="https://ninjatables.com/wp-content/uploads/2022/09/WP-Post-Table-2-scaled.webp" alt=""></li><li>Switch your selected post types from left to right, and move on to the next.</li><li>The properties you pick from the left will be the column of your post-data table. These properties are the columns in your table. Select the properties you want and transfer them from left to right. Then you can set multiple conditions for the properties of your post if you wish.</li><li>Save the settings after all the configuration is set up. Then you can view the output of this setup.</li><li>Now, all the post items have been added here. The post table also has paginations &amp; you can search for any posts from this table. <img src="https://ninjatables.com/wp-content/uploads/2022/09/WP-Post-Table-3-scaled.webp" alt=""> Go to the <strong>Query Settings</strong> tab of that post table. Scroll down, and here you will get two options, one is <strong>Conditions</strong> &amp; the other one is <strong>Meta Query</strong>.</li></ul><h2 id="conditions-in-custom-post-type" tabindex="-1"><strong>Conditions</strong> in Custom Post Type <a class="header-anchor" href="#conditions-in-custom-post-type" aria-label="Permalink to &quot;**Conditions** in Custom Post Type&quot;">​</a></h2><p>Table Query can be performed using Conditions based on the available fields.</p><ul><li><strong>Query Limit for Frontend:</strong> This enables you to specify how many posts/CPTs you want to show in total in the Frontend &amp; if you want to show all, you can leave them blank.</li><li>**Order by Column: **You can select your preferred column by which the table will be sorted.</li><li>**Order by Type: **There are only two options to sort the table rows. <strong>Ascending</strong> or <strong>Descending</strong>.</li><li>By clicking on the <strong>+</strong> icon, you can add as many conditions as you want. Let&#39;s look at an example where we can add a condition to find out the column, which is the ID equal** to 129**. <img src="https://ninjatables.com/wp-content/uploads/2022/09/WP-Post-Table-4-scaled.webp" alt="Conditions"></li><li>Now, see how these conditions work. It should show only the ID where the ID number is 129. <img src="https://ninjatables.com/wp-content/uploads/2023/02/WP-Post-Table-Condition-Preview.png" alt="Result of Conditions"></li></ul><h2 id="meta-query" tabindex="-1"><strong>Meta Query</strong> <a class="header-anchor" href="#meta-query" aria-label="Permalink to &quot;**Meta Query**&quot;">​</a></h2><p>You can add an additional meta query here to filter the table rows. If you want to apply a meta query, you need the meta key, which will be compared to the value of your columns. For instance, in this case, the <strong>meta key</strong> is the <strong>acf_demo</strong>, and the value <strong>ACF Demo Example</strong> will be** In** the meta key. It will then display only the row with the <strong>Meta name</strong>* *ACF Demo Example. See the below screenshot - <img src="https://ninjatables.com/wp-content/uploads/2022/09/WP-Post-Table-5-scaled.webp" alt="Meta Query"> Don&#39;t forget to click the <strong>Update</strong> button when the configuration is done! This is also applicable to other **custom post **types!</p>',10)])])}const m=e(n,[["render",i]]);export{u as __pageData,m as default};
